parameters.jsCode:
// Datos que necesitamos: la respuesta de la IA y el contexto de Airtable
const ia = $json.output;
const propiedades = $('Agrupar propiedades').first().json.propiedades;
const consultaId = $('Airtable - Registrar consulta').first().json.id;

// 1. PROPIEDAD: el código de la IA tiene que existir en Airtable
const prop = propiedades.find(p => p.fields.Codigo === ia.propiedad_codigo) || null;

// 2. FECHAS: n8n verifica lo que dijo la IA
let fechasEstado = ia.fechas_estado;
let checkin = ia.fecha_checkin;
let checkout = ia.fecha_checkout;

if (fechasEstado === 'completas') {
  const inicio = DateTime.fromISO(checkin);
  const fin = DateTime.fromISO(checkout);
  const hoy = $now.startOf('day');
  const noches = fin.diff(inicio, 'days').days;
  // Válidas si: existen, no están en el pasado y la estadía es de 1 a 60 noches
  const validas = inicio.isValid && fin.isValid && inicio >= hoy && noches >= 1 && noches <= 60;
  if (!validas) {
    fechasEstado = 'ambiguas';
    checkin = null;
    checkout = null;
  }
} else {
  checkin = null;
  checkout = null;
}

// 3. SERVICIOS: n8n compara contra los servicios reales de la propiedad
const serviciosProp = prop?.fields.Servicios || [];
const confirmados = ia.servicios_consultados.filter(s => serviciosProp.includes(s));
const sinDato = ia.servicios_consultados.filter(s => !confirmados.includes(s));

// 4. CAPACIDAD: ¿entran todos los huéspedes?
const superaCapacidad = Boolean(prop && ia.cantidad_huespedes && ia.cantidad_huespedes > prop.fields.Capacidad);

return {
  json: {
    consulta_id: consultaId,
    categoria: ia.categoria,
    categorias_adicionales: ia.categorias_adicionales.filter(c => c !== ia.categoria),
    urgencia: ia.urgencia,
    sentimiento: ia.sentimiento,
    resumen: ia.resumen,
    propiedad_id: prop ? prop.id : null,
    propiedad_codigo: prop ? prop.fields.Codigo : null,
    propiedad_activa: prop ? Boolean(prop.fields.Activa) : null,
    fechas_estado: fechasEstado,
    fecha_checkin: checkin,
    fecha_checkout: checkout,
    cantidad_huespedes: ia.cantidad_huespedes,
    supera_capacidad: superaCapacidad,
    servicios_confirmados: confirmados,
    servicios_sin_dato: sinDato,
    propiedad_nombre: prop ? prop.fields.Nombre : null,
    propiedad_capacidad: prop ? prop.fields.Capacidad : null,
    propiedad_checkin_desde: prop ? prop.fields['Check-in desde'] : null,
    propiedad_checkout_hasta: prop ? prop.fields['Check-out hasta'] : null,
    propiedad_instrucciones: prop ? prop.fields['Instrucciones de acceso'] : null,
    propiedades_activas: propiedades
      .filter(p => p.fields.Activa)
      .map(p => `${p.fields.Nombre} (${p.fields.Barrio}, hasta ${p.fields.Capacidad} personas)`)
  }
};

